def norm(s):
    tr=str(s or '').strip()
    tr=tr.replace('İ','i').replace('I','ı').lower().replace('ı','i')
    for a,b in [('ğ','g'),('ü','u'),('ş','s'),('ö','o'),('ç','c')]: tr=tr.replace(a,b)
    tr=re.sub(r'[^\w+/.-]+',' ',tr,flags=re.UNICODE)
    return re.sub(r'\s+',' ',tr).strip()

def slug(s):
    x=norm(s)
    x=re.sub(r'[^a-z0-9]+','-',x).strip('-')
    return x[:80]

all_text='\n'.join(x['text'] for x in texts)
normalized_text_items=[{**x, 'normText': norm(x['text'])} for x in texts]
all_norm='\n'.join(x['normText'] for x in normalized_text_items)

def find_examples(term, aliases=None, maxn=2):
    aliases=aliases or []
    keys=[term]+aliases
    keys_norm=[norm(k) for k in keys if k]
    ex=[]
    for item in normalized_text_items:
        n=item['normText']
        if any(k and k in n for k in keys_norm):
            ex.append({
                'sourceFilePath': item['path'],
                'text': item['text'][:420]
            })
            if len(ex)>=maxn: break
    return ex

def count_occ(term, aliases=None):
    keys=[norm(term)]+[norm(a) for a in (aliases or [])]
    keys=[k for k in keys if k]
    count=0
    for item in normalized_text_items:
        t=item['normText']
        if any(k in t for k in keys): count+=1
    return count

# concise builder
def e(term, sub, short, detail, pearl, diff, nested=None, aliases=None, priority='P1', leak='low'):
    return dict(term=term, aliases=aliases or [term], subcategory=sub, shortDefinition=short, detail=detail, pearl=pearl, diff=diff, nested=nested or [], priority=priority, answerLeakRisk=leak)

